from ext import *
ext('c10_eng_ch15',[
C("🏔️","नेपाल और पहाड़ी जीवन",["नेपाल हिमालय की गोद में बसा है","पहाड़ी रास्ते संकरे और खड़े","सड़कें कम, पीठ पर सामान ज़्यादा","कुली गाँवों की जीवन-रेखा"],"इस कविता को समझने के लिए पहले नेपाल के पहाड़ी जीवन को समझिए। नेपाल हिमालय की गोद में बसा देश है। वहाँ के कई गाँवों में आज भी गाड़ी की सड़क नहीं पहुँची। रास्ते संकरे हैं और खड़ी चढ़ाई वाले हैं। ऐसे में नमक, अनाज, कपड़े और निर्माण का सामान पीठ पर लादकर पहुँचाया जाता है। यह काम कुली करते हैं। वे एक पट्टे की मदद से बोझ को माथे पर टिकाते हैं और घंटों चलते हैं। इसलिए कुली पहाड़ी गाँवों की जीवन-रेखा कहे जा सकते हैं, पर उनकी मेहनत को बहुत कम सम्मान मिलता है।"),
C("🎒","कुली का एक दिन",["सुबह अँधेरे में उठना","भारी बोझ और खड़ी चढ़ाई","थोड़ा सा भोजन","शाम को थककर गहरी नींद"],"कुली का एक दिन सोचिए। वह सुबह अँधेरे में उठता है। पीठ और माथे पर पचास-साठ किलो का बोझ लादता है। फिर पूरे दिन खड़ी चढ़ाई चढ़ता है। रास्ते में थोड़ा सा सादा खाना मिल जाए तो बहुत है। शाम को जब मंज़िल पर पहुँचता है, तो उसे मिलती है बहुत थोड़ी मज़दूरी। फिर वह किसी पत्थर या ज़मीन पर ही थककर सो जाता है। कवि की नज़र इसी सोते हुए कुली पर पड़ती है और उनका मन करुणा से भर जाता है।"),
C("😴","नींद का राज्य",["नींद ही उसकी अमीरी है","सपनों में वह बोझ से मुक्त","जागते हुए ग़रीबी, सोते हुए राजा","कवि की सहानुभूति"],"कविता की सबसे सुंदर कल्पना यह है कि जागते हुए कुली ग़रीब है, पर सोते हुए वह नींद के समृद्ध राज्य में पहुँच जाता है। नींद में न बोझ है, न थकान, न मालिक की डाँट। सपनों में शायद वह अपने घर, बच्चों और खेतों को देखता है। यहाँ कवि ने दिखाया है कि ग़रीब आदमी के पास सुख का सबसे बड़ा साधन उसकी नींद है। इसी विरोध यानी कंट्रास्ट से कविता का भाव बहुत गहरा हो जाता है। परीक्षा में इस कल्पना का उल्लेख ज़रूर कीजिए।"),
C("🎭","कंट्रास्ट यानी विरोध",["जागना बनाम सोना","ग़रीबी बनाम नींद की अमीरी","आराम करते यात्री बनाम बोझ ढोता कुली","इससे करुणा गहरी होती है"],"कविता में कवि ने विरोध का सुंदर प्रयोग किया है। एक तरफ़ आराम से चलने वाले यात्री हैं और दूसरी तरफ़ बोझ से झुका हुआ कुली। एक तरफ़ जागते हुए की ग़रीबी है और दूसरी तरफ़ नींद की अमीरी। जब दो विपरीत बातें साथ रखी जाती हैं, तो पाठक के मन पर असर ज़्यादा पड़ता है। इसे ही अलंकार की भाषा में विरोधाभास कहा जा सकता है। परीक्षा में काव्य सौंदर्य लिखते समय यह बिंदु अलग से लिखिए, क्योंकि यही कविता की असली ताक़त है।"),
C("✍️","देवकोटा का परिचय",["नेपाल के महाकवि","मुना मदन उनका प्रसिद्ध काव्य","ग़रीबों के प्रति गहरी करुणा","कविताएँ नेपाली में, यहाँ अनुवाद"],"लक्ष्मी प्रसाद देवकोटा को नेपाल का महाकवि कहा जाता है। उनका लोकप्रिय काव्य मुना मदन नेपाल के घर-घर में पढ़ा और गाया जाता है। उनकी कविताओं में ग़रीबों और मेहनतकशों के लिए गहरी करुणा दिखती है। उन्होंने समाज की असमानता पर भी खुलकर लिखा। यह कविता मूल रूप से नेपाली में थी, और हम इसका अंग्रेज़ी अनुवाद पढ़ रहे हैं। इसलिए कभी-कभी भाषा थोड़ी अलग लगती है, पर भाव वही रहता है। परीक्षा के लिए कवि का देश, प्रसिद्ध रचना और विषय याद रखिए।"),
C("📘","अनुवाद क्या होता है",["एक भाषा से दूसरी भाषा","भाव वही, शब्द अलग","अनुवादक पुल का काम करता है","अनुवाद से साहित्य दुनिया तक पहुँचता है"],"इस कविता के बहाने अनुवाद को भी समझ लीजिए। अनुवाद का मतलब है किसी रचना को एक भाषा से दूसरी भाषा में ले जाना। इसमें भाव वही रहता है, पर शब्द बदल जाते हैं। अनुवादक एक पुल की तरह होता है, जो दो भाषाओं को जोड़ता है। अनुवाद की वजह से नेपाली कविता हम तक अंग्रेज़ी के रास्ते पहुँची। इसी तरह प्रेमचंद और टैगोर जैसे हमारे लेखक भी अनुवाद से दुनिया भर में पढ़े जाते हैं। अगर आपको दो भाषाएँ आती हैं, तो अनुवाद करना बहुत अच्छा अभ्यास है।"),
C("📝","शब्दार्थ दोहराइए",["पोर्टर यानी कुली","बर्डन यानी बोझ","वियरी यानी थका हुआ","वेजेज़ और रैग्ड"],"चलिए शब्दों को दोबारा दोहराते हैं। पोर्टर यानी कुली, बर्डन यानी बोझ, वियरी यानी थका हुआ, वेजेज़ यानी मज़दूरी और रैग्ड यानी फटा पुराना। इनके साथ स्लीप यानी सोना, माउंटेन यानी पहाड़ और क्लाइम्ब यानी चढ़ना भी याद कर लीजिए। अब एक छोटा खेल खेलिए। हर शब्द से एक वाक्य बनाइए, जैसे द पोर्टर इज़ वियरी। फिर पाँचों वाक्यों को कॉपी में लिख लीजिए। इस तरह आपका शब्द-भंडार भी बढ़ेगा और वाक्य बनाने की आदत भी पड़ेगी।"),
C("⏳","प्रेज़ेंट कंटिन्यूअस दोबारा",["इज़, एम, आर के साथ क्रिया में आई एन जी","अभी चल रहा काम बताता है","ही इज़ कैरिंग अ लोड","दे आर क्लाइम्बिंग द हिल"],"आज का व्याकरण है प्रेज़ेंट कंटिन्यूअस, यानी जो काम अभी हो रहा है। इसका नियम सरल है। इज़, एम या आर लगाइए और क्रिया में आई एन जी जोड़ दीजिए। जैसे द पोर्टर इज़ स्लीपिंग, यानी कुली सो रहा है। ही इज़ कैरिंग अ हैवी लोड, यानी वह भारी बोझ उठा रहा है। दे आर क्लाइम्बिंग द माउंटेन, यानी वे पहाड़ चढ़ रहे हैं। एक बात ध्यान रखिए, एक व्यक्ति के लिए इज़ और कई लोगों के लिए आर आता है। आई के साथ हमेशा एम लगता है। अपने आसपास हो रहे पाँच कामों पर वाक्य बनाइए।"),
C("🤝","श्रम का सम्मान",["हर काम बराबर सम्मान का","मज़दूर को उचित मज़दूरी","बच्चों से मज़दूरी अपराध","मेहनत से ही देश बनता है"],"इस कविता का सबसे बड़ा संदेश है श्रम का सम्मान। मकान, सड़क, पुल और रेलगाड़ी, सब कुछ मज़दूरों के हाथों से बनता है। फिर भी उन्हें अक्सर कम मज़दूरी और कम इज़्ज़त मिलती है। हमें समझना चाहिए कि कोई काम छोटा या बड़ा नहीं होता। मज़दूर को उसकी मेहनत का पूरा हक़ मिलना चाहिए। बच्चों से मज़दूरी करवाना क़ानूनन अपराध है, क्योंकि उनका हक़ पढ़ने और खेलने का है। अगली बार जब आप किसी कुली या मज़दूर को देखें, तो मुस्कुराकर धन्यवाद कहिए।"),
C("🚆","बिहार और प्रवासी मज़दूर",["बिहार के लाखों लोग बाहर काम करते हैं","परिवार से दूर कठिन जीवन","उनकी मेहनत से शहर चलते हैं","शिक्षा से बेहतर अवसर"],"बिहार से बहुत से लोग रोज़गार के लिए दूसरे राज्यों में जाते हैं। वे खेतों, कारख़ानों, निर्माण स्थलों और रेलवे स्टेशनों पर कठिन मेहनत करते हैं। परिवार से दूर रहकर वे घर पैसे भेजते हैं। उनकी स्थिति बहुत हद तक कविता के कुली जैसी ही है। इसलिए यह कविता हमें अपने ही आसपास की कहानी लगती है। पढ़ाई का महत्व भी यहीं समझ में आता है, क्योंकि अच्छी शिक्षा से बेहतर नौकरी और सम्मानजनक जीवन के रास्ते खुलते हैं। इसलिए मन लगाकर पढ़िए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि कौन हैं और किस देश के","कुली का वर्णन कीजिए","उसे नींद में क्या मिलता है","कविता का संदेश लिखिए"],"अब परीक्षा के प्रश्नों पर नज़र डालते हैं। पहला, कवि कौन हैं और किस देश के? उत्तर, लक्ष्मी प्रसाद देवकोटा, नेपाल के। दूसरा, कुली का वर्णन कीजिए। उत्तर, वह भारी बोझ उठाता है, फटे कपड़े पहनता है, थका रहता है और बहुत कम मज़दूरी पाता है। तीसरा, उसे नींद में क्या मिलता है? उत्तर, नींद के समृद्ध राज्य में शांति और सुख। चौथा, संदेश, श्रमिकों का सम्मान कीजिए। उत्तर पूरे वाक्य में लिखिए और जहाँ हो सके कविता का संदर्भ दीजिए।"),
Q("अगर आपके गाँव का कोई मज़दूर थका हुआ दिखे, तो आप क्या करेंगे?","उसे पानी या सहारा दूँगा, सम्मान से बात करूँगा और उसकी मेहनत की कद्र करूँगा।","एक सोचने वाला प्रश्न। अगर आपके गाँव या मोहल्ले में कोई मज़दूर थका हुआ दिखे, तो आप क्या करेंगे? कुछ पल सोचिए। ... आप उसे पानी पिला सकते हैं, सम्मान से बात कर सकते हैं और उसकी मेहनत की कद्र कर सकते हैं। छोटी सी दयालुता भी किसी का पूरा दिन बदल सकती है। यही इस कविता की असली सीख है।"),
Q("कविता में कुली और सोने की अवस्था में क्या विरोध दिखाया गया है?","जागते हुए वह ग़रीब और थका है, पर सोते हुए नींद के समृद्ध राज्य में सुखी है।","एक और प्रश्न। कविता में कुली की जागने और सोने की अवस्था में क्या विरोध दिखाया गया है? सोचिए। ... उत्तर, जागते हुए कुली ग़रीब, थका हुआ और बोझ से दबा है, पर सोते हुए वह नींद के समृद्ध राज्य में पहुँचकर सुख पाता है। यही कंट्रास्ट कविता को प्रभावशाली बनाता है।"),
],7)
